-- Real schedule data pipeline (Launch Readiness > Content & distribution,
-- Blocker): lineup/set-time data has lived as a hardcoded SETS array in
-- App.jsx, hand-edited every time a festival or year was added. That's fine
-- for a handful of days but doesn't scale, and it means shipping a new
-- festival's times requires a code change + redeploy instead of just adding
-- rows. Moves the factual part of that data (artist/day/stage/times/genre)
-- into a real table -- adding a festival/year going forward is a SQL
-- insert here, not an App.jsx edit.
--
-- match/sounds_like/sources are NOT real per-user data -- they're
-- simulated stand-ins for a recommendation engine that doesn't exist yet
-- (see the comment at the top of App.jsx). Carried over as-is so behavior
-- doesn't change, but they're demo values, not something a real "add a
-- festival" workflow needs to fill in truthfully.

create table if not exists festival_sets (
  id bigint primary key,
  festival_id text not null,
  day_id text not null,
  artist text not null,
  stage_id text not null,
  start_min integer not null,
  end_min integer not null,
  match integer,
  genre text,
  sounds_like text,
  sources text[] not null default '{}'
);

create index if not exists festival_sets_festival_idx on festival_sets (festival_id);

alter table festival_sets enable row level security;

-- Lineup data is public/promotional by nature (festivals publish their own
-- set times) -- readable by anyone, signed in or not. Writes only ever
-- happen from the SQL editor (or a future admin tool using the service
-- role), so there's deliberately no insert/update/delete policy here.
drop policy if exists "anyone can read festival sets" on festival_sets;
create policy "anyone can read festival sets"
  on festival_sets for select
  using (true);

on conflict (id) do nothing;
